-- Wrap auth/session function calls in RLS policy predicates in (SELECT ...) so Postgres
-- evaluates them once per statement (InitPlan) instead of once per row -- the
-- Supabase-documented RLS perf pattern. Predicate-equivalent (row visibility unchanged).
-- Generated by 'pgrls fix --rule PERF001' and verified (PERF001 -> 0). Refs #6.

-- [PERF001] Wrap auth function call(s) in policy 'tenant_isolation' on public.agent_capability_grants so Postgres can cache the result for the whole statement instead of re-evaluating per row.
ALTER POLICY tenant_isolation ON public.agent_capability_grants
    USING (workspace_id = CAST(NULLIF((SELECT current_setting(CAST('app.current_workspace_id' AS text), TRUE)), CAST('' AS text)) AS uuid));

